// Single source of settings and the planner prompt for this workflow. Other
// Code nodes read $('Config').first().json; the build injects
// config/config.local.json and prompts/planner.md here and nowhere else.
// @inject config as CONFIG
// @end-inject
// @inject prompts/planner.md as PROMPT_PLANNER
// @end-inject
return [{ json: { ...CONFIG, prompts: { planner: PROMPT_PLANNER } } }];

const CONFIG = $('Config').first().json;
// @inject src/normalize-item.js as normalize
// @end-inject
// @inject src/candidates.js as cand
// @end-inject
// @inject src/capacity.js as cap
// @end-inject
// @inject src/claude.js as claude
// @end-inject
// Deterministic part of the planning: free time, candidate ranking and the
// bounded model input (at most max_planner_candidates tasks). One item out.
const PROMPT = CONFIG.prompts.planner;
const tz = CONFIG.timezone;
const now = $now.setZone(tz);
const today = now.toISODate();
const pages = $('Fetch open items').first().json.results || [];
const items = pages.map((p) => normalize.fromNotionPage(p));
// Fetch calendar has "always output data": an empty day arrives as one empty item.
const events = $('Fetch calendar').all().map((i) => i.json).filter((e) => e && e.id);
const capacity = cap.computeCapacity({ date: today, timezone: tz, workStart: CONFIG.schedule.work_start, workEnd: CONFIG.schedule.work_end, events, bufferMin: CONFIG.schedule.meeting_buffer_min });
const { candidates, omitted } = cand.selectCandidates(items, { today, max: CONFIG.defaults.max_planner_candidates, defaultPriority: CONFIG.defaults.priority, defaultEstimate: CONFIG.defaults.estimate_min });
const fyi = cand.selectFyi(items);
const drafts = cand.selectDraftsWaiting(items);
const LANG = { ru: 'Russian', en: 'English', cs: 'Czech' };
const list = (arr, f) => (arr.length ? arr.map(f).join('\n') : '-');
const vars = {
  owner_name: CONFIG.owner.name,
  owner_context: CONFIG.owner.context,
  digest_language: LANG[CONFIG.language.digest] || CONFIG.language.digest,
  today,
  weekday: now.toFormat('cccc'),
  free_minutes: capacity.free_minutes,
  free_slots: list(capacity.free_slots, (s) => s.start + '-' + s.end + ' (' + s.minutes + ' min)'),
  meetings: list(capacity.meetings, (m) => (m.all_day ? 'all day: ' + m.title : m.start + '-' + m.end + ': ' + m.title)),
  omitted,
  candidates: candidates.map(({ id, title, kind, priority, due, days_to_due, overdue, age_days, estimate_min }) => ({ id, title, kind, priority, due, days_to_due, overdue, age_days, estimate_min })),
};
return [{ json: { today, capacity, candidates, omitted, fyi, drafts, request: claude.buildClaudeRequest(PROMPT, vars, CONFIG.models) } }];

const CONFIG = $('Config').first().json;
// @inject src/claude.js as claude
// @end-inject
// @inject src/feasibility.js as feas
// @end-inject
// @inject src/digest-format.js as digest
// @end-inject
// The code, not the model, has the last word on the arithmetic: the plan is
// trimmed to the free minutes, unknown IDs are dropped, then rendered twice.
const input = $('Prepare planner input').first().json;
const response = $input.first().json;
const lang = CONFIG.language.digest;
const L = digest.labels(lang);
const raw = claude.parseClaudeResponse(response);
const plan = feas.enforceFeasibility(raw, { candidates: input.candidates, freeMinutes: input.capacity.free_minutes, today: input.today, workDays: CONFIG.schedule.digest_days, overflowReason: L.overflow });
const model = digest.buildDigestSections({ date: input.today, capacity: input.capacity, plan, fyi: input.fyi, drafts: input.drafts, omitted: input.omitted }, lang);
const page = {
  parent: { database_id: CONFIG.notion.digests_database_id },
  properties: {
    Name: { title: [{ type: 'text', text: { content: model.header } }] },
    Date: { date: { start: input.today } },
    'Free minutes': { number: plan.free_minutes },
    'Planned minutes': { number: plan.planned_minutes },
    Overloaded: { checkbox: plan.overloaded },
  },
  children: digest.renderNotionBlocks(model),
};
return [{ json: { today: input.today, messages: digest.renderTelegram(model), page, fyi_ids: input.fyi.map((f) => f.id), usage_planner: claude.usageOf(response) } }];

// The Notion page is written first so the digest is kept even if Telegram
// fails; the messages (already split under 4096 chars) come from Build digest.
const { messages } = $('Build digest').first().json;
return messages.map((text, index) => ({ json: { text, index } }));

// Runs only after the digest was delivered. Closing FYI items is the one
// automatic status change the rules allow (hard rule 3). No items: the run ends.
const { fyi_ids } = $('Build digest').first().json;
return fyi_ids.map((id) => ({ json: { id } }));
